{"content":""""Local verification plan mirroring the acceptance criteria."""
import socket
import struct
import threading

from client import KVStoreClient, KVStoreError

PASS = []
FAIL = []


def check(name, fn):
    try:
        fn()
    except Exception as exc:  # noqa: BLE001 - test harness reports, not swallows
        FAIL.append(name)
        print(f"FAIL {name}: {type(exc).__name__}: {exc}")
    else:
        PASS.append(name)
        print(f"ok   {name}")


def fresh():
    c = KVStoreClient()
    c.connect()
    return c


def t_connection():
    c = fresh()
    assert c._sock is not None
    c.close()


def t_set_get():
    c = fresh()
    try:
        assert c.set(b"hello", b"world") is True
        assert c.get(b"hello") == b"world"
    finally:
        c.close()


def t_list():
    c = fresh()
    try:
        c.set(b"lk1", b"1")
        c.set(b"lk2", b"2")
        keys = c.list_keys()
        assert b"lk1" in keys and b"lk2" in keys, keys
    finally:
        c.close()


def t_delete():
    c = fresh()
    try:
        c.set(b"del1", b"x")
        assert c.delete(b"del1") is True
        try:
            c.get(b"del1")
        except KeyError:
            pass
        else:
            raise AssertionError("GET after DELETE did not raise KeyError")
    finally:
        c.close()


def t_binary():
    c = fresh()
    try:
        key = b"bin\xffkey\nnl"
        val = b"\x00\x01\x02\n\r\non-print\xff\xfe\x00end"
        assert c.set(key, val) is True
        assert c.get(key) == val, "binary roundtrip mismatch"
    finally:
        c.delete(b"bin\xffkey\nnl")
        c.close()


def t_large():
    c = fresh()
    try:
        val = bytes(range(256)) * 256  # 64KB
        assert len(val) == 65536
        c.set(b"big", val)
        assert c.get(b"big") == val
    finally:
        c.delete(b"big")
        c.close()


def t_get_missing():
    c = fresh()
    try:
        try:
            c.get(b"definitely-not-here-12345")
        except KeyError:
            return
        raise AssertionError("no KeyError")
    finally:
        c.close()


def t_delete_missing():
    c = fresh()
    try:
        assert c.delete(b"definitely-not-here-12345") is False
    finally:
        c.close()


def t_magic_sent():
    # Spy socket: capture what the client sends, replay an OK response.
    sent = {}

    class SpySock:
        def __init__(self):
            self._resp = struct.pack("!BBI", 0x42, 0x00, 0)
            self._pos = 0

        def settimeout(self, _t):
            pass

        def sendall(self, data):
            sent.setdefault("data", b"")
            sent["data"] += data

        def recv(self, n):
            chunk = self._resp[self._pos:self._pos + n]
            self._pos += len(chunk)
            return chunk

        def shutdown(self, *_a):
            pass

        def close(self):
            pass

    c = KVStoreClient()
    c._sock = SpySock()  # type: ignore[assignment]
    assert c.set(b"k", b"v") is True
    raw = sent["data"]
    magic, op, ln = struct.unpack("!BBI", raw[:6])
    assert magic == 0x42, f"magic {magic:#x}"
    assert op == 0x01 and ln == 3, (op, ln)
    c.close()


def t_bad_magic_response():
    class BadSock:
        def settimeout(self, _t):
            pass

        def sendall(self, _d):
            pass

        def recv(self, n):
            return b"\x00" * n  # wrong magic, full header

        def shutdown(self, *_a):
            pass

        def close(self):
            pass

    c = KVStoreClient()
    c._sock = BadSock()  # type: ignore[assignment]
    try:
        c.get(b"k")
    except KVStoreError:
        return
    raise AssertionError("bad magic not rejected")


def t_malformed_truncated():
    class ShortSock:
        def settimeout(self, _t):
            pass

        def sendall(self, _d):
            pass

        def recv(self, _n):
            return b""  # immediate EOF

        def shutdown(self, *_a):
            pass

        def close(self):
            pass

    c = KVStoreClient(timeout=2.0)
    c._sock = ShortSock()  # type: ignore[assignment]
    try:
        c.get(b"k")
    except (ConnectionResetError, KVStoreError, TimeoutError):
        return
    raise AssertionError("truncated response not surfaced")


def t_reconnect():
    c = fresh()
    try:
        c.set(b"rc", b"1")
        # Kill the underlying connection to simulate a drop.
        assert c._sock is not None
        c._sock.close()
        c._sock = None
        assert c.get(b"rc") == b"1"  # lazy reconnect
    finally:
        c.delete(b"rc")
        c.close()


def t_rapid():
    c = fresh()
    try:
        for i in range(1000):
            k = f"r{i}".encode()
            c.set(k, k)
            assert c.get(k) == k
        for i in range(1000):
            c.delete(f"r{i}".encode())
    finally:
        c.close()


def t_concurrent():
    errors = []

    def worker(n):
        try:
            c = fresh()
            try:
                for i in range(50):
                    k = f"c{n}-{i}".encode()
                    c.set(k, b"v")
                    assert c.get(k) == b"v"
                    c.delete(k)
            finally:
                c.close()
        except Exception as exc:  # noqa: BLE001
            errors.append(exc)

    threads = [threading.Thread(target=worker, args=(n,)) for n in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert not errors, errors[:1]


def t_server_rejects_garbage_magic():
    s = socket.create_connection(("localhost", 9999), timeout=3)
    s.settimeout(3)
    try:
        s.sendall(struct.pack("!BBI", 0x00, 0x02, 1) + b"k")
        resp = s.recv(6)
        magic, code, ln = struct.unpack("!BBI", resp)
        assert (magic, code, ln) == (0x42, 0xFF, 0), (magic, code, ln)
    finally:
        s.close()


for name, fn in sorted({k: v for k, v in globals().items()
                        if k.startswith("t_")}.items()):
    check(name, fn)
print(f"\n{len(PASS)} passed, {len(FAIL)} failed")
raise SystemExit(1 if FAIL else 0)
