            self._sent_hdr = False

        def settimeout(self, _t):
            pass

        def sendall(self, _d):
            pass

        def recv(self, _n):
            if not self._sent_hdr:
                self._sent_hdr = True
                return self._hdr
            raise socket.timeout("stalled")

        def shutdown(self, *_a):
            pass

        def close(self):
            pass

    c = KVStoreClient(timeout=2.0)
    c._sock = StallSock()  # type: ignore[assignment]
    # Point reconnects at a dead port so the retry cannot mask the timeout.
    c._port = 1
    start = time.monotonic()
    try:
        c.get(b"k")
    except (TimeoutError, ConnectionRefusedError, OSError, KVStoreError):
        elapsed = time.monotonic() - start
        assert elapsed < 30, f"hung too long: {elapsed:.1f}s"
        return
    raise AssertionError("stalled payload did not raise")


